<?php
/**
 * SEO — defaults, indexing switches, redirects and duplicate-slug detection.
 *
 * The checks on this screen are real: duplicate titles/descriptions are computed
 * from the actual catalogue and CMS rows, and the sitemap/robots previews are
 * generated by the same code the public site serves.
 */

declare(strict_types=1);
// Refuse direct HTTP requests: this file is only ever included by the panel.
if (!defined('OMNI_PANEL')) {
    http_response_code(403);
    exit('Forbidden');
}


use Omni\Admin\Activity;
use Omni\Admin\CalcRepo;
use Omni\Admin\Csrf;
use Omni\Admin\Flash;
use Omni\Admin\Pagination;
use Omni\Cms;
use Omni\Db;
use Omni\Seo;

if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    Csrf::requirePost();
    Csrf::assert();
    $do = post('do', '') ?? '';

    if ($do === 'redirect_add') {
        $from = trim((string) (post('from_path', '') ?? ''));
        $to = trim((string) (post('to_path', '') ?? ''));
        $code = post_int('status_code', 301);
        if (!in_array($code, [301, 302, 307, 308, 410], true)) {
            $code = 301;
        }
        $from = '/' . ltrim($from, '/');
        $errors = [];
        if ($from === '/' || $from === '/admin') {
            $errors[] = 'That path cannot be redirected.';
        }
        if ($to === '') {
            $errors[] = 'Enter where the old address should go.';
        }
        if (Db::one('SELECT id FROM redirects WHERE from_path = ?', [$from]) !== null) {
            $errors[] = 'A redirect for ' . $from . ' already exists.';
        }
        if ($errors !== []) {
            foreach ($errors as $error) {
                Flash::error($error);
            }
        } else {
            Db::insert('redirects', ['from_path' => $from, 'to_path' => $to, 'status_code' => $code, 'enabled' => 1, 'note' => mb_substr((string) (post('note', '') ?? ''), 0, 255)]);
            Activity::log('redirect_created', 'redirect', $from, 'Redirect ' . $from . ' → ' . $to);
            Flash::success('Redirect created.');
        }
        redirect_to(admin_url('seo', ['tab' => 'redirects']));
    }

    if ($do === 'redirect_toggle') {
        $id = post_int('id');
        Db::exec('UPDATE redirects SET enabled = 1 - enabled WHERE id = ?', [$id]);
        Flash::success('Redirect updated.');
        redirect_to(admin_url('seo', ['tab' => 'redirects']));
    }

    if ($do === 'redirect_delete') {
        Db::delete('redirects', 'id = ?', [post_int('id')]);
        Activity::log('redirect_deleted', 'redirect', (string) post_int('id'), 'Deleted a redirect');
        Flash::success('Redirect removed.');
        redirect_to(admin_url('seo', ['tab' => 'redirects']));
    }

    if ($do === 'save_settings') {
        $result = \Omni\Admin\Settings::save('seo', post_deep('settings'));
        foreach ($result['errors'] as $error) {
            Flash::error($error);
        }
        Flash::success('SEO settings saved.');
        redirect_to(admin_url('seo'));
    }

    redirect_to(admin_url('seo'));
}

$tab = (string) (request('tab') ?? 'general');
$values = Cms::settings();

/* duplicate detection across calculators + pages + posts */
$titles = [];
$duplicates = [];
foreach (CalcRepo::rows() as $row) {
    $title = trim((string) ($row['metaTitle'] !== '' ? $row['metaTitle'] : $row['name']));
    $titles[mb_strtolower($title)][] = ['label' => $row['name'], 'url' => admin_url('calculator-edit', ['path' => $row['sourcePath']])];
}
foreach (Db::all('SELECT title, slug, meta_title FROM pages') as $page) {
    $key = mb_strtolower(trim((string) ($page['meta_title'] !== '' ? $page['meta_title'] : $page['title'])));
    $titles[$key][] = ['label' => (string) $page['title'], 'url' => admin_url('pages', ['q' => (string) $page['slug']])];
}
foreach (Db::all('SELECT title, id, meta_title FROM posts') as $post) {
    $key = mb_strtolower(trim((string) ($post['meta_title'] !== '' ? $post['meta_title'] : $post['title'])));
    $titles[$key][] = ['label' => (string) $post['title'], 'url' => admin_url('blog-edit', ['id' => (int) $post['id']])];
}
foreach ($titles as $key => $group) {
    if ($key !== '' && count($group) > 1) {
        $duplicates[] = ['title' => $key, 'items' => $group];
    }
}

$paginator = new Pagination((int) Db::value('SELECT COUNT(*) FROM redirects', [], 0), 30, request_int('pg', 1));
$redirects = Db::all('SELECT * FROM redirects ORDER BY id DESC LIMIT ' . $paginator->perPage . ' OFFSET ' . $paginator->offset());

$sitemapPreview = mb_substr(Seo::sitemap(), 0, 1600);
$robotsPreview = Seo::robots();

$pageTitle = 'SEO';
$title = $pageTitle;
$wide = true;

render('seo', compact('tab', 'values', 'duplicates', 'redirects', 'paginator', 'sitemapPreview', 'robotsPreview', 'pageTitle', 'title', 'wide'));
